// analyzer/tuples.ts:54
pub(crate) const MAX_INFERRED_TUPLE_ENTRY_COUNT: u32 = 256;

// analyzer/tuples.ts:56
/// TS defaults: isUnpacked = false.
pub fn make_tuple_object(
    evaluator: &TypeEvaluator,
    type_args: &[TupleTypeArg],
    is_unpacked: bool,
) -> P<Type> {
    let tuple_class = evaluator.get_tuple_class_type();
    if let Some(tuple_class) = tuple_class
        && is_instantiable_class(tuple_class.0)
    {
        return convert_to_instance(
            specialize_tuple_class(
                tuple_class,
                type_args,
                /* isTypeArgExplicit */ true,
                is_unpacked,
            )
            .0,
            true,
        );
    }

    UnknownType::create(false).0
}

// analyzer/tuples.ts:65
pub fn get_type_of_tuple(
    evaluator: &TypeEvaluator,
    node: TupleNode,
    flags: EvalFlags,
    inference_context: Option<&InferenceContext>,
    node_info: &AnalyzerNodeInfoAccessor,
) -> P<TypeResult> {
    let mut flags = flags;
    if flags.any(EvalFlags::TypeExpression)
        && node.parent.get().map(|parent| parent.node_type) != Some(ParseNodeType::Argument)
    {
        // This is allowed inside of an index trailer, specifically
        // to support Tuple[()], which is the documented way to annotate
        // a zero-length tuple.
        let diag = DiagnosticAddendum::new();
        diag.add_message(LocAddendum::use_tuple_instead());
        evaluator.add_diagnostic(
            DiagnosticRule::reportInvalidTypeForm,
            &(LocMessage::tuple_in_annotation()
                + &diag.get_string(
                    DEFAULT_MAX_DIAGNOSTIC_DEPTH,
                    DEFAULT_MAX_DIAGNOSTIC_LINE_COUNT,
                )),
            node.0,
            None,
        );

        return P::new_eval(TypeResult::new(UnknownType::create(false).0));
    }

    if flags.any(EvalFlags::InstantiableType)
        && node.d().items.borrow().is_empty()
        && inference_context.is_none()
    {
        return P::new_eval(TypeResult {
            is_empty_tuple_shorthand: Some(true),
            ..TypeResult::new(make_tuple_object(evaluator, &[], false))
        });
    }

    flags &=
        !(EvalFlags::TypeExpression | EvalFlags::StrLiteralAsType | EvalFlags::InstantiableType);

    // If the expected type is a union, recursively call for each of the subtypes
    // to find one that matches.
    let mut expected_type = inference_context.map(|context| context.expected_type);
    let mut expected_type_contains_any =
        inference_context.is_some_and(|context| is_any(context.expected_type));

    if let Some(context) = inference_context
        && is_union(context.expected_type)
    {
        let mut matching_subtype: Option<P<Type>> = None;

        do_for_each_subtype(
            context.expected_type,
            &mut |subtype, _, _| {
                if is_any(subtype) {
                    expected_type_contains_any = true;
                }

                if matching_subtype.is_none() {
                    let subtype_result = evaluator.use_speculative_mode(
                        Some(node.0),
                        &mut || {
                            get_type_of_tuple_with_context(
                                evaluator,
                                node,
                                flags,
                                &mut make_inference_context(Some(subtype), None, None).unwrap(),
                                node_info,
                            )
                        },
                        None,
                    );

                    if let Some(subtype_result) = subtype_result
                        && evaluator.assign_type(
                            subtype,
                            subtype_result.type_.get(),
                            None,
                            None,
                            AssignTypeFlags::Default,
                            0,
                        )
                    {
                        matching_subtype = Some(subtype);
                    }
                }
            },
            /* sortSubtypes */ true,
        );

        expected_type = matching_subtype;
    }

    let mut expected_type_diag_addendum: Option<P<DiagnosticAddendum>> = None;
    if let Some(expected_type) = expected_type {
        let result = get_type_of_tuple_with_context(
            evaluator,
            node,
            flags,
            &mut make_inference_context(Some(expected_type), None, None).unwrap(),
            node_info,
        );

        if let Some(result) = result
            && !result.type_errors.get().unwrap_or(false)
        {
            return result;
        }

        expected_type_diag_addendum =
            result.and_then(|result| result.expected_type_diag_addendum.get());
    }

    let type_result = get_type_of_tuple_inferred(evaluator, node, flags);

    // If there was an expected type of Any, replace the resulting type
    // with Any rather than return a type with unknowns.
    if expected_type_contains_any {
        type_result.type_.set(AnyType::create(false).0);
    }

    let result = (*type_result).clone();
    result
        .expected_type_diag_addendum
        .set(expected_type_diag_addendum);
    P::new_eval(result)
}

// analyzer/tuples.ts:152
pub fn get_type_of_tuple_with_context(
    evaluator: &TypeEvaluator,
    node: TupleNode,
    flags: EvalFlags,
    inference_context: &mut InferenceContext,
    node_info: &AnalyzerNodeInfoAccessor,
) -> Option<P<TypeResult>> {
    inference_context.expected_type =
        transform_possible_recursive_type_alias(Some(inference_context.expected_type), 0).unwrap();
    if !is_class_instance(inference_context.expected_type) {
        return None;
    }

    let tuple_class = evaluator.get_tuple_class_type();
    let tuple_class = tuple_class.filter(|tuple_class| is_instantiable_class(tuple_class.0))?;

    let items = node.d().items.borrow().clone();

    // Build an array of expected types.
    let mut expected_types: Vec<P<Type>> = vec![];

    let expected_class = ClassType(inference_context.expected_type);
    let expected_tuple_type_args = expected_class.d().priv_.borrow().tuple_type_args.clone();
    if let Some(expected_tuple_type_args) =
        expected_tuple_type_args.filter(|_| is_tuple_class(expected_class))
    {
        expected_types = expected_tuple_type_args
            .iter()
            .map(|t| transform_possible_recursive_type_alias(Some(t.type_), 0).unwrap())
            .collect();
        let unbounded_index = expected_tuple_type_args.iter().position(|t| t.is_unbounded);
        if let Some(unbounded_index) = unbounded_index {
            if expected_types.len() > items.len() {
                expected_types.remove(unbounded_index);
            } else {
                while expected_types.len() < items.len() {
                    expected_types.insert(unbounded_index, expected_types[unbounded_index]);
                }
            }
        }
    } else {
        let tuple_constraints = ConstraintTracker::new();
        if !add_constraints_for_expected_type(
            evaluator,
            ClassType::clone_as_instance(tuple_class, true),
            inference_context.expected_type,
            tuple_constraints,
            Some(&get_type_var_scopes_for_node(node.0, node_info.reader())),
            Some(node.start.get()),
        ) {
            return None;
        }

        // `as ClassType`: a non-class result has no `typeArgs`, so it returns below.
        let specialized_tuple = ClassType::cast(evaluator.solve_and_apply_constraints(
            tuple_class.0,
            tuple_constraints,
            None,
            None,
        ));
        let type_args = specialized_tuple.and_then(|t| t.d().priv_.borrow().type_args.clone());
        let type_args = type_args.filter(|type_args| type_args.len() == 1)?;

        let homogenous_type =
            transform_possible_recursive_type_alias(Some(type_args[0]), 0).unwrap();
        for _ in 0..items.len() {
            expected_types.push(homogenous_type);
        }
    }

    let entry_type_results: Vec<P<TypeResult>> = items
        .iter()
        .enumerate()
        .map(|(index, &expr)| {
            evaluator.get_type_of_expression(
                expr,
                flags | EvalFlags::StripTupleLiterals,
                make_inference_context(
                    expected_types.get(index).copied(),
                    inference_context.is_type_incomplete,
                    None,
                )
                .as_mut(),
            )
        })
        .collect();
    let is_incomplete = entry_type_results
        .iter()
        .any(|result| result.is_incomplete.get().unwrap_or(false));

    // Copy any expected type diag addenda for precision error reporting.
    let mut expected_type_diag_addendum: Option<P<DiagnosticAddendum>> = None;
    if entry_type_results
        .iter()
        .any(|result| result.expected_type_diag_addendum.get().is_some())
    {
        let addendum = DiagnosticAddendum::new();
        for result in &entry_type_results {
            if let Some(result_addendum) = result.expected_type_diag_addendum.get() {
                addendum.add_addendum(result_addendum);
            }
        }
        expected_type_diag_addendum = Some(addendum);
    }

    // If the tuple contains a very large number of entries, it's probably
    // generated code. If we encounter type errors, don't bother building
    // the full tuple type.
    let type_ = if items.len() > MAX_INFERRED_TUPLE_ENTRY_COUNT as usize
        && entry_type_results
            .iter()
            .any(|result| result.type_errors.get().unwrap_or(false))
    {
        make_tuple_object(
            evaluator,
            &[TupleTypeArg {
                type_: UnknownType::create(false).0,
                is_unbounded: true,
                is_optional: None,
            }],
            false,
        )
    } else {
        make_tuple_object(
            evaluator,
            &evaluator.build_tuple_types_list(
                &entry_type_results,
                /* stripLiterals */ false,
                /* convertModule */ false,
            ),
            false,
        )
    };

    Some(P::new_eval(TypeResult {
        expected_type_diag_addendum: Cell::new(expected_type_diag_addendum),
        is_incomplete: Cell::new(Some(is_incomplete)),
        ..TypeResult::new(type_)
    }))
}

// analyzer/tuples.ts:251
pub fn get_type_of_tuple_inferred(
    evaluator: &TypeEvaluator,
    node: TupleNode,
    flags: EvalFlags,
) -> P<TypeResult> {
    let items = node.d().items.borrow().clone();
    let entry_type_results: Vec<P<TypeResult>> = items
        .iter()
        .map(|&expr| {
            evaluator.get_type_of_expression(expr, flags | EvalFlags::StripTupleLiterals, None)
        })
        .collect();
    let is_incomplete = entry_type_results
        .iter()
        .any(|result| result.is_incomplete.get().unwrap_or(false));

    // If the tuple contains a very large number of entries, it's probably
    // generated code. Rather than taking the time to evaluate every entry,
    // simply return an unknown type in this case.
    if items.len() > MAX_INFERRED_TUPLE_ENTRY_COUNT as usize {
        return P::new_eval(TypeResult::new(make_tuple_object(
            evaluator,
            &[TupleTypeArg {
                type_: UnknownType::create(false).0,
                is_unbounded: true,
                is_optional: None,
            }],
            false,
        )));
    }

    let type_ = make_tuple_object(
        evaluator,
        &evaluator.build_tuple_types_list(
            &entry_type_results,
            flags.any(EvalFlags::StripTupleLiterals),
            /* convertModule */ true,
        ),
        false,
    );

    if is_incomplete && get_container_depth(type_, 0) > MAX_INFERRED_CONTAINER_DEPTH {
        return P::new_eval(TypeResult::new(UnknownType::create(false).0));
    }

    P::new_eval(TypeResult {
        is_incomplete: Cell::new(Some(is_incomplete)),
        ..TypeResult::new(type_)
    })
}

// analyzer/tuples.ts:285
pub fn assign_tuple_type_args(
    evaluator: &TypeEvaluator,
    dest_type: ClassType,
    src_type: ClassType,
    diag: Option<P<DiagnosticAddendum>>,
    constraints: Option<P<ConstraintTracker>>,
    flags: AssignTypeFlags,
    recursion_count: u32,
) -> bool {
    let mut dest_type_args = dest_type
        .d()
        .priv_
        .borrow()
        .tuple_type_args
        .clone()
        .unwrap_or_default();
    let mut src_type_args = src_type
        .d()
        .priv_
        .borrow()
        .tuple_type_args
        .clone()
        .unwrap_or_default();

    if adjust_tuple_type_args(evaluator, &mut dest_type_args, &mut src_type_args, flags) {
        for arg_index in 0..src_type_args.len() {
            let entry_diag = diag.map(|diag| diag.create_addendum());
            let dest_arg_type = dest_type_args[arg_index].type_;
            let src_arg_type = src_type_args[arg_index].type_;

            // Handle the special case where the dest is a TypeVarTuple
            // and the source is a `*tuple[Any, ...]`. This is allowed.
            if is_type_var_tuple(dest_arg_type)
                && {
                    let priv_ = TypeVarType(dest_arg_type).d().priv_.borrow();
                    priv_.is_unpacked.unwrap_or(false) && !priv_.is_in_union.unwrap_or(false)
                }
                && is_tuple_gradual_form(src_arg_type).unwrap_or(false)
            {
                return true;
            }

            if !evaluator.assign_type(
                dest_arg_type,
                src_arg_type,
                entry_diag.map(|entry_diag| entry_diag.create_addendum()),
                constraints,
                flags,
                recursion_count,
            ) {
                if let Some(entry_diag) = entry_diag {
                    entry_diag.add_message(
                        LocAddendum::tuple_entry_type_mismatch()
                            .format(&[("entry", &(arg_index + 1).to_string())]),
                    );
                }
                return false;
            }
        }
    } else {
        let is_dest_indeterminate = dest_type_args
            .iter()
            .any(|t| t.is_unbounded || is_type_var_tuple(t.type_));

        if src_type_args
            .iter()
            .any(|t| t.is_unbounded || is_type_var_tuple(t.type_))
        {
            if is_dest_indeterminate {
                if let Some(diag) = diag {
                    diag.add_message(
                        LocAddendum::tuple_size_indeterminate_src_dest().format(&[(
                            "expected",
                            &(dest_type_args.len() as i64 - 1).to_string(),
                        )]),
                    );
                }
            } else if let Some(diag) = diag {
                diag.add_message(
                    LocAddendum::tuple_size_indeterminate_src()
                        .format(&[("expected", &dest_type_args.len().to_string())]),
                );
            }
        } else if is_dest_indeterminate {
            if let Some(diag) = diag {
                diag.add_message(
                    LocAddendum::tuple_size_mismatch_indeterminate_dest().format(&[
                        ("expected", &(dest_type_args.len() as i64 - 1).to_string()),
                        ("received", &src_type_args.len().to_string()),
                    ]),
                );
            }
        } else if let Some(diag) = diag {
            diag.add_message(LocAddendum::tuple_size_mismatch().format(&[
                ("expected", &dest_type_args.len().to_string()),
                ("received", &src_type_args.len().to_string()),
            ]));
        }

        return false;
    }

    true
}

// analyzer/tuples.ts:380
pub fn adjust_tuple_type_args(
    evaluator: &TypeEvaluator,
    dest_type_args: &mut Vec<TupleTypeArg>,
    src_type_args: &mut Vec<TupleTypeArg>,
    flags: AssignTypeFlags,
) -> bool {
    // JS `splice(start, deleteCount)` and `splice(start, 0, item)`, which clamp `start`.
    fn splice_remove(args: &mut Vec<TupleTypeArg>, start: i32, count: i32) -> Vec<TupleTypeArg> {
        let start = (start.max(0) as usize).min(args.len());
        let end = (start + count.max(0) as usize).min(args.len());
        args.drain(start..end).collect()
    }
    fn splice_insert(args: &mut Vec<TupleTypeArg>, start: i32, item: TupleTypeArg) {
        let start = (start.max(0) as usize).min(args.len());
        args.insert(start, item);
    }
    fn find_index(args: &[TupleTypeArg], predicate: impl Fn(&TupleTypeArg) -> bool) -> i32 {
        args.iter()
            .position(predicate)
            .map_or(-1, |index| index as i32)
    }

    let dest_unbounded_or_variadic_index = find_index(dest_type_args, |t| {
        t.is_unbounded || is_unpacked_type_var_tuple(t.type_) || is_unpacked_type_var(t.type_)
    });
    let mut src_unbounded_index = find_index(src_type_args, |t| t.is_unbounded);
    let src_variadic_index = find_index(src_type_args, |t| {
        is_unpacked_type_var_tuple(t.type_) || is_unpacked_type_var(t.type_)
    });

    if src_unbounded_index >= 0 {
        if is_any_or_unknown(src_type_args[src_unbounded_index as usize].type_) {
            // If the source contains an unbounded Any, expand it to match the dest length.
            let type_to_replicate = if !src_type_args.is_empty() {
                src_type_args[src_unbounded_index as usize].type_
            } else {
                AnyType::create(false).0
            };

            while src_type_args.len() < dest_type_args.len() {
                splice_insert(
                    src_type_args,
                    src_unbounded_index,
                    TupleTypeArg {
                        type_: type_to_replicate,
                        is_unbounded: true,
                        is_optional: None,
                    },
                );
            }

            if src_type_args.len() > dest_type_args.len() {
                splice_remove(src_type_args, src_unbounded_index, 1);

                // Invalidate the stale index after removal.
                src_unbounded_index = -1;
            }
        } else if dest_unbounded_or_variadic_index < 0 {
            // If the source contains an unbounded type but the dest does not, it's incompatible.
            return false;
        }
    }

    // If the dest contains an unbounded Any, expand it to match the source length.
    if dest_unbounded_or_variadic_index >= 0
        && dest_type_args[dest_unbounded_or_variadic_index as usize].is_unbounded
        && is_any_or_unknown(dest_type_args[dest_unbounded_or_variadic_index as usize].type_)
    {
        while dest_type_args.len() < src_type_args.len() {
            let item = dest_type_args[dest_unbounded_or_variadic_index as usize].clone();
            splice_insert(dest_type_args, dest_unbounded_or_variadic_index, item);
        }
    }

    // Remove any optional parameters from the end of the two lists until the lengths match.
    while src_type_args.len() > dest_type_args.len()
        && src_type_args[src_type_args.len() - 1]
            .is_optional
            .unwrap_or(false)
    {
        src_type_args.pop();
    }

    while dest_type_args.len() > src_type_args.len()
        && dest_type_args[dest_type_args.len() - 1]
            .is_optional
            .unwrap_or(false)
    {
        dest_type_args.pop();
    }

    let src_args_to_capture = src_type_args.len() as i32 - dest_type_args.len() as i32 + 1;
    let mut skip_adjust_src = false;

    // If we're doing reverse type mappings and the source contains a TypeVarTuple,
    // we need to adjust the dest so the reverse type mapping assignment
    // can be performed.
    if flags.any(AssignTypeFlags::Contravariant) {
        let dest_args_to_capture = dest_type_args.len() as i32 - src_type_args.len() as i32 + 1;

        if src_variadic_index >= 0 && dest_args_to_capture >= 0 {
            // If the only removed arg from the dest type args is itself a variadic,
            // don't bother adjusting it.
            let skip_adjustment = dest_args_to_capture == 1
                && is_type_var_tuple(dest_type_args[src_variadic_index as usize].type_);
            let tuple_class = evaluator.get_tuple_class_type();

            if !skip_adjustment
                && let Some(tuple_class) = tuple_class
                && is_instantiable_class(tuple_class.0)
            {
                let removed_args =
                    splice_remove(dest_type_args, src_variadic_index, dest_args_to_capture);

                // Package up the remaining type arguments into a tuple object.
                let variadic_tuple = ClassType::clone_as_instance(
                    specialize_tuple_class(
                        tuple_class,
                        &removed_args
                            .iter()
                            .map(|type_arg| TupleTypeArg {
                                type_: type_arg.type_,
                                is_unbounded: type_arg.is_unbounded,
                                is_optional: type_arg.is_optional,
                            })
                            .collect::<Vec<_>>(),
                        /* isTypeArgExplicit */ true,
                        /* isUnpacked */ true,
                    ),
                    true,
                );

                splice_insert(
                    dest_type_args,
                    src_variadic_index,
                    TupleTypeArg {
                        type_: variadic_tuple.0,
                        is_unbounded: false,
                        is_optional: None,
                    },
                );
            }

            skip_adjust_src = true;
        }
    } else if dest_unbounded_or_variadic_index >= 0 && src_args_to_capture >= 0 {
        // If the dest contains a variadic element, determine which source
        // args map to this element and package them up into an unpacked tuple.
        if is_type_var_tuple(dest_type_args[dest_unbounded_or_variadic_index as usize].type_) {
            let tuple_class = evaluator.get_tuple_class_type();

            if let Some(tuple_class) = tuple_class
                && is_instantiable_class(tuple_class.0)
            {
                let removed_args = splice_remove(
                    src_type_args,
                    dest_unbounded_or_variadic_index,
                    src_args_to_capture,
                );

                // If we're left with a single unpacked variadic type var, there's no
                // need to wrap it in a nested tuple.
                let variadic_tuple: P<Type> = if removed_args.len() == 1
                    && is_unpacked_type_var_tuple(removed_args[0].type_)
                {
                    removed_args[0].type_
                } else {
                    // Package up the remaining type arguments into a tuple object.
                    ClassType::clone_as_instance(
                        specialize_tuple_class(
                            tuple_class,
                            &removed_args
                                .iter()
                                .map(|type_arg| TupleTypeArg {
                                    type_: type_arg.type_,
                                    is_unbounded: type_arg.is_unbounded,
                                    is_optional: type_arg.is_optional,
                                })
                                .collect::<Vec<_>>(),
                            /* isTypeArgExplicit */ true,
                            /* isUnpacked */ true,
                        ),
                        true,
                    )
                    .0
                };

                splice_insert(
                    src_type_args,
                    dest_unbounded_or_variadic_index,
                    TupleTypeArg {
                        type_: variadic_tuple,
                        is_unbounded: false,
                        is_optional: None,
                    },
                );
            }

            skip_adjust_src = true;
        }
    }

    if !skip_adjust_src && dest_unbounded_or_variadic_index >= 0 && src_args_to_capture >= 0 {
        // If possible, package up the source entries that correspond to
        // the dest unbounded tuple. This isn't possible if the source contains
        // an unbounded tuple outside of this range.
        if src_unbounded_index < 0
            || (src_unbounded_index >= dest_unbounded_or_variadic_index
                && src_unbounded_index < dest_unbounded_or_variadic_index + src_args_to_capture)
        {
            let removed_arg_types: Vec<P<Type>> = splice_remove(
                src_type_args,
                dest_unbounded_or_variadic_index,
                src_args_to_capture,
            )
            .iter()
            .map(|t| {
                if is_type_var(t.type_) && is_unpacked_type_var_tuple(t.type_) {
                    return TypeVarType::clone_for_unpacked(
                        TypeVarType(t.type_),
                        /* isInUnion */ true,
                    )
                    .0;
                }
                t.type_
            })
            .collect();

            splice_insert(
                src_type_args,
                dest_unbounded_or_variadic_index,
                TupleTypeArg {
                    type_: if !removed_arg_types.is_empty() {
                        combine_types(&removed_arg_types, None)
                    } else {
                        AnyType::create(false).0
                    },
                    is_unbounded: false,
                    is_optional: None,
                },
            );
        }
    }

    dest_type_args.len() == src_type_args.len()
}

// analyzer/tuples.ts:548
pub fn get_sliced_tuple_type(
    evaluator: &TypeEvaluator,
    tuple_type: ClassType,
    slice_node: SliceNode,
) -> Option<P<Type>> {
    // We don't handle step values.
    let tuple_type_args = tuple_type.d().priv_.borrow().tuple_type_args.clone();
    let tuple_type_args = tuple_type_args.filter(|_| slice_node.d().step_value.get().is_none())?;

    let start_value = get_tuple_slice_param(
        evaluator,
        slice_node.d().start_value.get(),
        0.0,
        &tuple_type_args,
    );
    let end_value = get_tuple_slice_param(
        evaluator,
        slice_node.d().end_value.get(),
        tuple_type_args.len() as f64,
        &tuple_type_args,
    );

    let (Some(start_value), Some(end_value)) = (start_value, end_value) else {
        return None;
    };
    if end_value < start_value {
        return None;
    }

    let sliced_type_args = &tuple_type_args[start_value as usize..end_value as usize];
    Some(
        ClassType::clone_as_instance(
            specialize_tuple_class(tuple_type, sliced_type_args, true, false),
            true,
        )
        .0,
    )
}

// analyzer/tuples.ts:575
pub fn expand_tuple(tuple_type: ClassType, max_expansion: u32) -> Option<Vec<P<Type>>> {
    let tuple_type_args = tuple_type.d().priv_.borrow().tuple_type_args.clone();
    let tuple_type_args = tuple_type_args.filter(|tuple_type_args| {
        is_tuple_class(tuple_type)
            && !tuple_type_args
                .iter()
                .any(|type_arg| type_arg.is_unbounded || is_type_var_tuple(type_arg.type_))
    })?;

    let mut types_to_combine: Vec<ClassType> = vec![tuple_type];
    let mut index = 0;

    while index < tuple_type_args.len() {
        let elem_type = tuple_type_args[index].type_;
        if is_union(elem_type) {
            let mut new_types_to_combine: Vec<ClassType> = vec![];

            for &type_to_combine in &types_to_combine {
                do_for_each_subtype(
                    elem_type,
                    &mut |subtype, _, _| {
                        let mut new_type_args = type_to_combine
                            .d()
                            .priv_
                            .borrow()
                            .tuple_type_args
                            .clone()
                            .unwrap();
                        new_type_args[index] = TupleTypeArg {
                            type_: subtype,
                            is_unbounded: false,
                            is_optional: None,
                        };
                        new_types_to_combine.push(ClassType::clone_as_instance(
                            specialize_tuple_class(type_to_combine, &new_type_args, true, false),
                            true,
                        ));
                    },
                    false,
                );
            }
            types_to_combine = new_types_to_combine;
        }

        if types_to_combine.len() > max_expansion as usize {
            return None;
        }

        index += 1;
    }

    if types_to_combine.len() == 1 {
        None
    } else {
        Some(types_to_combine.iter().map(|t| t.0).collect())
    }
}

// analyzer/tuples.ts:612
pub(crate) fn get_tuple_slice_param(
    evaluator: &TypeEvaluator,
    expression: Option<ExpressionNode>,
    default_value: f64,
    tuple_type_args: &[TupleTypeArg],
) -> Option<f64> {
    let mut value = default_value;

    if let Some(expression) = expression {
        let val_type = evaluator
            .get_type_of_expression(expression, EvalFlags::None, None)
            .type_
            .get();
        if !is_class_instance(val_type)
            || !ClassType::is_built_in(ClassType(val_type), Some(&["int".to_string()]))
            || !is_literal_type(ClassType(val_type))
        {
            return None;
        }

        // `literalValue as number`. A bigint literal is beyond 2^53; JavaScript throws when
        // it adds one to a number below, which this port does not reproduce.
        value = match ClassType(val_type).d().priv_.borrow().literal_value.clone() {
            Some(LiteralValue::Number(n)) => n,
            Some(LiteralValue::Bigint(n)) => n.to_f64(),
            _ => unreachable!("an int literal holds a number"),
        };
        let unbounded_index = tuple_type_args
            .iter()
            .position(|type_arg| type_arg.is_unbounded || is_type_var_tuple(type_arg.type_))
            .map_or(-1.0, |index| index as f64);

        if value < 0.0 {
            value += tuple_type_args.len() as f64;
            if unbounded_index >= 0.0 && value <= unbounded_index {
                return None;
            } else if value < 0.0 {
                return Some(0.0);
            }
        } else if unbounded_index >= 0.0 && value > unbounded_index {
            return None;
        } else if value > tuple_type_args.len() as f64 {
            return Some(tuple_type_args.len() as f64);
        }
    }

    Some(value)
}
